#[inline]
pub fn png_do_write_interlace(
    mut row_info: png_row_infop,
    mut row: png_bytep,
    mut pass: c_int,
) {
    unsafe {
        static PNG_PASS_START: [png_byte; 7] = [0, 4, 0, 2, 0, 1, 0];
        static PNG_PASS_INC: [png_byte; 7] = [8, 8, 4, 4, 2, 2, 1];

        if pass >= 6 {
            return;
        }

        let pass_usize = pass as usize;
        let start = PNG_PASS_START[pass_usize] as png_uint_32;
        let inc = PNG_PASS_INC[pass_usize] as png_uint_32;

        let pixel_depth = (*row_info).pixel_depth as c_int;
        let row_width = (*row_info).width;

        match pixel_depth {
            1 => {
                let mut dp = row;
                let mut d: png_byte = 0;
                let mut shift: u32 = 7;
                let mut i = start;
                while i < row_width {
                    let byte_index = (i >> 3) as isize;
                    let bit_shift = 7u32.wrapping_sub(i & 7);
                    // SAFETY: `row` points to the row buffer and `byte_index` is derived from `i < row_width`,
                    // matching the original access pattern within the source row storage.
                    let src = *row.offset(byte_index);
                    d |= (((src as u32) >> bit_shift) as png_byte & 0x1) << shift;
                    if shift == 0 {
                        // SAFETY: `dp` advances within the destination prefix of the same row buffer exactly as in the original code.
                        *dp = d;
                        // SAFETY: advancing by 1 stays within the packed destination region, same as original.
                        dp = dp.offset(1);
                        d = 0;
                        shift = 7;
                    } else {
                        shift -= 1;
                    }
                    i = i.wrapping_add(inc);
                }
                if shift != 7 {
                    // SAFETY: partial final destination byte is written to the current valid destination position, same as original.
                    *dp = d;
                }
            }
            2 => {
                let mut dp = row;
                let mut d: png_byte = 0;
                let mut shift: u32 = 6;
                let mut i = start;
                while i < row_width {
                    let byte_index = (i >> 2) as isize;
                    let bit_shift = ((3u32.wrapping_sub(i & 3)) << 1) as u32;
                    // SAFETY: `row` points to the row buffer and `byte_index` is derived from `i < row_width`,
                    // matching the original access pattern within the source row storage.
                    let src = *row.offset(byte_index);
                    d |= (((src as u32) >> bit_shift) as png_byte & 0x3) << shift;
                    if shift == 0 {
                        // SAFETY: `dp` advances within the destination prefix of the same row buffer exactly as in the original code.
                        *dp = d;
                        // SAFETY: advancing by 1 stays within the packed destination region, same as original.
                        dp = dp.offset(1);
                        d = 0;
                        shift = 6;
                    } else {
                        shift -= 2;
                    }
                    i = i.wrapping_add(inc);
                }
                if shift != 6 {
                    // SAFETY: partial final destination byte is written to the current valid destination position, same as original.
                    *dp = d;
                }
            }
            4 => {
                let mut dp = row;
                let mut d: png_byte = 0;
                let mut shift: u32 = 4;
                let mut i = start;
                while i < row_width {
                    let byte_index = (i >> 1) as isize;
                    let bit_shift = ((1u32.wrapping_sub(i & 1)) << 2) as u32;
                    // SAFETY: `row` points to the row buffer and `byte_index` is derived from `i < row_width`,
                    // matching the original access pattern within the source row storage.
                    let src = *row.offset(byte_index);
                    d |= (((src as u32) >> bit_shift) as png_byte & 0x0f) << shift;
                    if shift == 0 {
                        // SAFETY: `dp` advances within the destination prefix of the same row buffer exactly as in the original code.
                        *dp = d;
                        // SAFETY: advancing by 1 stays within the packed destination region, same as original.
                        dp = dp.offset(1);
                        d = 0;
                        shift = 4;
                    } else {
                        shift -= 4;
                    }
                    i = i.wrapping_add(inc);
                }
                if shift != 4 {
                    // SAFETY: partial final destination byte is written to the current valid destination position, same as original.
                    *dp = d;
                }
            }
            _ => {
                let pixel_bytes = (pixel_depth >> 3) as png_size_t;
                let mut dp = row;
                let mut i = start;
                while i < row_width {
                    // SAFETY: source offset is within the original row buffer for pixel `i`, same as original code.
                    let sp = row.offset((i as png_size_t).wrapping_mul(pixel_bytes) as isize);
                    if dp != sp {
                        // SAFETY: source and destination ranges are valid for `pixel_bytes` and may overlap, exactly matching original `memcpy` usage constraints from caller behavior.
                        memcpy(dp as *mut c_void, sp as *const c_void, pixel_bytes as size_t);
                    }
                    // SAFETY: destination advances by one packed pixel each iteration within the row buffer, same as original.
                    dp = dp.offset(pixel_bytes as isize);
                    i = i.wrapping_add(inc);
                }
            }
        }

        let new_width = (row_width as c_uint)
            .wrapping_add(inc as c_uint)
            .wrapping_sub(1)
            .wrapping_sub(start as c_uint)
            .wrapping_div(inc as c_uint) as png_uint_32;
        (*row_info).width = new_width;
        (*row_info).rowbytes = if pixel_depth >= 8 {
            (new_width as png_size_t).wrapping_mul((pixel_depth as png_size_t) >> 3)
        } else {
            (new_width as png_size_t)
                .wrapping_mul(pixel_depth as png_size_t)
                .wrapping_add(7)
                >> 3
        };
    }
}

